<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Arena;
use App\Domain\Arena\Repository\DuelQuestionSelectorInterface; use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionRecord; use Doctrine\ORM\EntityManagerInterface;
final class DoctrineDuelQuestionSelector implements DuelQuestionSelectorInterface { public function __construct(private readonly EntityManagerInterface $em){} public function selectPublishedBalanced(array $subjects,array $excluded,int $count):array { if($subjects===[])return[];$ids=[];for($i=0;$i<$count;$i++){ $subject=$subjects[$i%count($subjects)];$q=$this->em->createQueryBuilder()->select('q.id')->from(QuestionRecord::class,'q')->innerJoin('App\\Infrastructure\\Persistence\\Doctrine\\QuestionBank\\Entity\\QuestionTaxonomySubjectRecord','t','WITH','t.questionId=q.id')->where('q.status=:s')->andWhere('t.taxonomySubjectId=:subject')->andWhere($excluded==[]?'1=1':'q.id NOT IN (:excluded)')->setParameter('s','PUBLISHED')->setParameter('subject',$subject)->setParameter('excluded',$excluded)->orderBy('q.createdAt','ASC')->setMaxResults(1)->getQuery()->getSingleColumnResult();if($q===[])return[];$ids[]=$q[0];$excluded[]=$q[0];}return$ids;} }
